-- KAIROS-T-0790 (COLLIERY-I-0683, KAIROS-A-0087): the default templates
-- with guidance. Generated from crates/kairos-db/default_templates/ and
-- crates/kairos-db/src/default_templates.rs; a test of that module checks
-- that this text is the same.
--
-- WHAT THIS DOES TO THE DATA
--
-- An in-place upgrade of public.system_templates, the source of the
-- templates of a new tenant, going forward only: no item
-- changes. A system template that an operator did not change (its content is the old
-- seed) gets the new content. A changed one keeps its content. Each system
-- template with no use_when gets one. The templates of the new types (task,
-- bug, tech debt, support, initiative, strategy, ADR, Design Doc, Runbook,
-- Postmortem) are added; a slug or a fixed type that the table has is not
-- added again. The table is small.
--
-- Re-runnable.

UPDATE public.system_templates
SET content = E'## Context\n\n*Optional when a Design Doc exists: write its code. Else, say the problem and the capability areas in a few sentences.*\n\n## Requirements\n\n*A requirement says a behavior that the system guarantees, not how the system does it. A test must be able to check it. Use "must", not "should". Number each one: REQ-area.number.*\n\n### 1. Capability area\n\n*Use the capability areas of the Design Doc. Say what this area owns.*\n\n**REQ-1.1: Name.** What the system must do, in one to three sentences. Give the reason when it is not clear.\n\n### Cross-cutting requirements\n\n*Write the requirements for all areas: onboarding, ownership, change management.*\n\n**REQ-X.1: Name.** \n\n## Non-functional requirements\n\n*Each one has a target that you can measure, or a condition that you can test. Write "a lookup adds less than 10 ms", not "fast".*\n\n### Performance\n\n**NFR-1.1: Name.** \n\n### Availability and reliability\n\n*Say what continues to work when a part fails, and what the system can lose.*\n\n**NFR-2.1: Name.** \n\n### Security\n\n**NFR-3.1: Name.** \n\n### Service levels\n\n*Give the service level objective of each main workflow. It must agree with the service levels of the systems that this system uses. It must also agree with the systems that use it. When you do not know them, write that as a risk with an owner.*\n\n**NFR-4.1: Name.** \n\n### Escalation\n\n*For each failure that you know or expect, say who gets the alert, and by which tool. Say how fast, and who owns the response. Cover at least: a failed dependency, late or old data, and the service down.*\n\n**NFR-5.1: Escalation for [failure].** When [condition], [team or role] gets an alert by [paging tool] in [time]. [Team] owns the response in [time].\n\n## Out of scope\n\n*List what this PRD does not cover, so that nobody expects it.*\n\n## Open questions\n\n*List what you do not know yet, and who owns each answer.*\n\n## Exit criteria\n\n*Publish the PRD only when each item is true.*\n\n- [ ] Each requirement has a number and a test can check it.\n- [ ] Each non-functional requirement has a target or a condition.\n- [ ] The people who own the product reviewed and approved it.\n',
    updated_at = now()
WHERE slug = 'prd'
  AND content = E'# Product Requirements Document\n\n## Problem\n\n## Goals\n\n## Non-Goals\n\n## Requirements\n\n## Open Questions\n';

UPDATE public.system_templates
SET content = E'## Actors\n\n*An actor is a person, a role or an external system that uses this system. For each one, say what it needs and what it gives. Say what breaks for it when this system is not there. Name the teams in each role today.*\n\n### [Actor]\n\nTeams in this role today: \n\n## External systems\n\n*List each system that this system uses or connects to. Say what it gives, and if it is a hard dependency, under evaluation, or deployed but not used.*\n\n### [External system]\n\n## Context diagram\n\n*Draw the system as a box, with the actors and the external systems around it. Label each arrow with what moves. A rough diagram is better than a paragraph. Kairos draws a mermaid block.*\n\n```mermaid\nflowchart LR\n  actor[Actor] -->|what it sends| system[This system]\n```\n\n## Key interactions\n\n*Write one row for each arrow of the diagram.*\n\n| Actor or system | Capability area | Interaction |\n|---|---|---|\n|  |  |  |\n\n## Exit criteria\n\n*Publish the document only when each item is true.*\n\n- [ ] Each actor and each external system is in the document.\n- [ ] The diagram has each actor and each system.\n- [ ] The table has one row for each arrow of the diagram.\n',
    updated_at = now()
WHERE slug = 'system_context'
  AND content = E'# System Context\n\n## Overview\n\n## Actors\n\n## External Systems\n\n## Data Flows\n';

UPDATE public.system_templates
SET content = E'*This document frames each decision. It does not make it. When the team makes a decision, record it in an ADR.*\n\n## Decision 1: [area]\n\n### What to decide\n\n*Write the decision as a question or a choice. Write "Avro, Protobuf or JSON Schema for the messages", not "how we store data".*\n\n### Why it matters\n\n*Say what goes wrong later when the choice is bad or late. Say what waits for this decision.*\n\n### Constraints\n\n- \n\n### Required capabilities\n\n*List what the chosen option must be able to do.*\n\n- \n\n## Decision dependencies\n\n*Add a row when one decision must come before another.*\n\n| Decision | Depends on | Why |\n|---|---|---|\n|  |  |  |\n\n## Open questions\n\n*List what you do not know yet, and who owns each answer.*\n\n- \n\n## Exit criteria\n\n*Publish the document only when each item is true.*\n\n- [ ] Each open decision has its question, its constraints and its required capabilities.\n- [ ] The table shows the order of the decisions.\n- [ ] Each decision that the team made has an ADR.\n',
    updated_at = now()
WHERE slug = 'architecture_framing'
  AND content = E'# Architecture Framing\n\n## Context\n\n## Constraints\n\n## Options Considered\n\n## Decision Drivers\n';

UPDATE public.system_templates
SET content = E'*Keep the charter to one page. Show it to the team before you finish it.*\n\n## Mission\n\n*In one or two sentences: what the team exists to do, and for whom. Which problem has no owner when the team does not exist?*\n\n## Responsibility\n\n*List what the team owns: services, products, infrastructure, processes. Also list what it does not own: that is as important.*\n\n**We own:**\n\n- \n\n**We do not own:**\n\n- \n\n## What we deliver\n\n*Say who the customers of the team are and what the team gives them. What can they do because the team exists?*\n\n## How we work\n\n*Say how the team works: its values, its quality, and how it takes requests and sets priorities. Say what other teams can count on.*\n\n## Standards we follow\n\n*List the standards of the organization that the team must follow, with a link to each one. For example: how work goes from an idea to delivery, change management, incident response, on call, postmortems.*\n\n- \n\n## Operational readiness\n\n*Track the readiness checklist of the organization here. The manager signs off when each item is done.*\n\n## Exit criteria\n\n*Publish the charter only when each item is true.*\n\n- [ ] The team reviewed the charter.\n- [ ] The manager signed off the readiness checklist.\n',
    updated_at = now()
WHERE slug = 'team_charter'
  AND content = E'# Team Charter\n\n## Mission\n\n## Scope\n\n## Ways of Working\n\n## Success Measures\n';

UPDATE public.system_templates
SET content = E'## Values\n\n*List three to five values. For each one, write one behavior that shows it.*\n\n## Agreements\n\n*Write each agreement as a rule that a person can follow. Example: "We answer a review request in one working day."*\n\n## Communication\n\n*Say which channel the team uses for what, and how fast a person answers in each one.*\n\n## Conflict resolution\n\n*Say the steps when two members do not agree, and who decides at the end.*\n\n## Exit criteria\n\n*Publish the contract only when each item is true.*\n\n- [ ] Each member of the team agrees with it.\n',
    updated_at = now()
WHERE slug = 'social_contract'
  AND content = E'# Social Contract\n\n## Values\n\n## Agreements\n\n## Communication\n\n## Conflict Resolution\n';

UPDATE public.system_templates
SET content = E'*This template has sections for many types of vision. Delete each optional section that does not apply.*\n\n## Purpose\n\n*Say why this vision exists, and what it aims to do.*\n\n## Product or solution overview\n\n*Optional: delete this section for a vision of the organization or of a process. Describe the product, who it is for, and what it improves.*\n\n## Current state\n\n*Say where things are today: the baseline.*\n\n## Future state\n\n*Describe the target: what is different when the vision is true.*\n\n## Major features\n\n*Optional: delete this section when this is not the vision of a product. Write one line for each feature, with its value.*\n\n- \n\n## Business requirements\n\n*Optional: delete this section for a vision that is only technical or only about a product.*\n\n- \n\n## Success criteria\n\n*Say how you will know that the vision is true. Use a number where you can.*\n\n## Principles\n\n*Write the rules that choose between two good options.*\n\n## Constraints\n\n*List the known limits and boundaries.*\n\n## Exit criteria\n\n*Publish the vision only when each item is true.*\n\n- [ ] The purpose and the success criteria are clear.\n- [ ] The current state and the future state are written.\n- [ ] The principles are agreed.\n- [ ] The people who own the vision reviewed and approved it.\n',
    updated_at = now()
WHERE slug = 'company_vision'
  AND content = E'# Company Vision\n\n## Where We Are Going\n\n## Why It Matters\n\n## How We Will Know\n';

UPDATE public.system_templates
SET content = E'*This template has sections for many types of vision. Delete each optional section that does not apply.*\n\n## Purpose\n\n*Say why this vision exists, and what it aims to do.*\n\n## Product or solution overview\n\n*Optional: delete this section for a vision of the organization or of a process. Describe the product, who it is for, and what it improves.*\n\n## Current state\n\n*Say where things are today: the baseline.*\n\n## Future state\n\n*Describe the target: what is different when the vision is true.*\n\n## Major features\n\n*Optional: delete this section when this is not the vision of a product. Write one line for each feature, with its value.*\n\n- \n\n## Business requirements\n\n*Optional: delete this section for a vision that is only technical or only about a product.*\n\n- \n\n## Success criteria\n\n*Say how you will know that the vision is true. Use a number where you can.*\n\n## Principles\n\n*Write the rules that choose between two good options.*\n\n## Constraints\n\n*List the known limits and boundaries.*\n\n## Exit criteria\n\n*Publish the vision only when each item is true.*\n\n- [ ] The purpose and the success criteria are clear.\n- [ ] The current state and the future state are written.\n- [ ] The principles are agreed.\n- [ ] The people who own the vision reviewed and approved it.\n',
    updated_at = now()
WHERE slug = 'product_vision'
  AND content = E'# Product Vision\n\n## Purpose\n\n## Who It Is For\n\n## Current State\n\n## Future State\n\n## Principles\n\n## What It Is Not\n';

UPDATE public.system_templates
SET content = E'*Write one row for each term. Use the meaning that the organization uses, in one sentence. A longer term wins over a shorter one ("production document" before "production").*\n\n| Word | Part of speech | Meaning |\n|---|---|---|\n',
    updated_at = now()
WHERE slug = 'dictionary'
  AND content = E'# Dictionary\n\nThe terms of the organization. Write one row for each term. The organization has one dictionary, on the board strategy.\n\n| Word | Part of speech | Meaning |\n|---|---|---|\n';

UPDATE public.system_templates SET use_when = E'Use when the team can do the work in one piece, with one result that a person can check.' WHERE slug = 'task' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when the product does not do what it should do.' WHERE slug = 'bug' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when the code works, but a part of it makes the next change slow, risky or hard to read.' WHERE slug = 'tech_debt' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when a person or a team asks for help, and nobody has decided what to do yet.' WHERE slug = 'support' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when one objective needs more than one task, or the work of more than one person or team.' WHERE slug = 'initiative' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when the organization bets on a direction for many months, and many initiatives serve it.' WHERE slug = 'strategy' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when you make a decision that is hard to change later, or that other teams must follow.' WHERE slug = 'adr' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when you design a new system or a large feature. Start here: this document says which other documents the design needs.' WHERE slug = 'design_doc' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when you must say what a system must do, so that a team can build it and test it.' WHERE slug = 'prd' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when you must show who uses a system and which other systems it depends on.' WHERE slug = 'system_context' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when a design has open decisions, and the team must agree on each question before it chooses.' WHERE slug = 'architecture_framing' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when a service runs in production and a person on call must keep it working.' WHERE slug = 'runbook' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when an incident is over. Learn from it and track the fixes. Write it without blame.' WHERE slug = 'postmortem' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when a team starts, or its mission or its responsibilities change.' WHERE slug = 'team_charter' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when a team agrees how its members work together.' WHERE slug = 'social_contract' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when the organization says where it wants to be in some years. The organization has one.' WHERE slug = 'company_vision' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when you say what a product, a repository or a capability is for, and where it goes. It is not the vision of the organization.' WHERE slug = 'product_vision' AND use_when = '';

UPDATE public.system_templates SET use_when = E'Use when you define a term of the organization. The organization has one dictionary, on the board strategy.' WHERE slug = 'dictionary' AND use_when = '';

INSERT INTO public.system_templates (name, slug, content, item_type, task_type, use_when) VALUES
    ('Task', 'task', E'## Objective\n\n*Say in one to three sentences what this task does, and why. Name the request or the initiative that gave it.*\n\n## Acceptance Criteria\n\n*Write each criterion as one instruction that a person can test. Use the active voice and the present tense, in 20 words or fewer. Example: "A refused write names the missing field."*\n\n- [ ] \n\n## Implementation Notes\n\n*Optional: delete this section for a task that is not technical.*\n\n### Technical Approach\n\n*Say how you will do the work. Do not write file paths or code: they change.*\n\n### Dependencies\n\n*Name the tasks and the systems that this task needs. Kairos records a task that must finish first as a blocks edge.*\n\n### Risk Considerations\n\n*Say the technical risks, and how you will make each one smaller.*\n\n## Exit Criteria\n\n*Move the task to Completed only when each item is true.*\n\n- [ ] All acceptance criteria are met.\n- [ ] The implementation is tested.\n- [ ] The documentation is updated.\n- [ ] The work is ready for integration.\n', 'task', 'task', E'Use when the team can do the work in one piece, with one result that a person can check.'),
    ('Bug', 'bug', E'## Objective\n\n*Say in one or two sentences what the fix does.*\n\n## Impact Assessment\n\n*Give the facts. Write the steps from a known state, with the version and the environment. When you cannot reproduce the problem, write "Not reproduced" and say what you tried.*\n\n- **Affected Users**: the number or the percent of the users.\n- **Reproduction Steps**:\n  1. \n- **Expected vs Actual**: what should happen, and what happens.\n\n## Acceptance Criteria\n\n*Write each criterion as one instruction that a test can check. Include a test that fails before the fix and passes after it.*\n\n- [ ] \n\n## Implementation Notes\n\n### Technical Approach\n\n*Write the cause when you find it, with the evidence. Then say how you will fix it. Do not write file paths or code: they change.*\n\n### Dependencies\n\n*Name the tasks and the systems that the fix needs.*\n\n### Risk Considerations\n\n*Say what the fix can break, and how you will know.*\n\n## Exit Criteria\n\n*Move the bug to Completed only when each item is true.*\n\n- [ ] All acceptance criteria are met.\n- [ ] A test shows the fix.\n- [ ] The documentation is updated.\n- [ ] The fix is ready for integration.\n', 'task', 'bug', E'Use when the product does not do what it should do.'),
    ('Tech debt', 'tech_debt', E'## Objective\n\n*Say in one or two sentences what the change improves, and why now.*\n\n## Technical Debt Impact\n\n*Give one example for each item.*\n\n- **Current Problems**: what is difficult, slow or defective now.\n- **Benefits of Fixing**: what improves after the change.\n- **Risk Assessment**: the risks of no change.\n\n## Acceptance Criteria\n\n*Write each criterion as one instruction that a person can test. Include "The behavior does not change" and the tests that show it.*\n\n- [ ] \n\n## Implementation Notes\n\n### Technical Approach\n\n*Describe the shape that the code will have. Do not write file paths or code: they change.*\n\n### Dependencies\n\n*Name the tasks and the systems that the change needs.*\n\n### Risk Considerations\n\n*Say what can break, and name the tests that guard the behavior.*\n\n## Exit Criteria\n\n*Move the task to Completed only when each item is true.*\n\n- [ ] All acceptance criteria are met.\n- [ ] The tests pass, and the behavior does not change.\n- [ ] The documentation is updated.\n- [ ] The work is ready for integration.\n', 'task', 'tech_debt', E'Use when the code works, but a part of it makes the next change slow, risky or hard to read.'),
    ('Support', 'support', E'## Request\n\n*Write the request in the words of the person who asked. Name the person or the team, and how to reach them.*\n\n## Context\n\n*Give the facts that you have: the account, the version, the time, the links.*\n\n## Triage\n\n*Write the decision and the reason: planned work, work now, another team, or will not do. A person on the board decides; an agent writes a proposal.*\n\n## Answer\n\n*Write what you told the person, and when.*\n\n## Exit criteria\n\n*Move the task to Completed only when each item is true.*\n\n- [ ] A person decided the triage, and the task says the decision.\n- [ ] The person who asked has an answer.\n', 'task', 'support', E'Use when a person or a team asks for help, and nobody has decided what to do yet.'),
    ('Initiative', 'initiative', E'*This template has sections for many types of initiatives. Delete each optional section that does not apply.*\n\n## Context\n\n*Say the background, and why the work is necessary now.*\n\n## Goals and non-goals\n\n*Keep one objective: work for a different objective goes to its own initiative. Also say what the initiative will not do.*\n\n**Goals:**\n\n- \n\n**Non-goals:**\n\n- \n\n## Requirements\n\n*Optional: keep this section when the initiative has many requirements. Number each one. Use "must", not "should".*\n\n### User requirements\n\n- **Users:** their background and their experience.\n- **What users expect:** \n- **Interfaces:** how users use the system.\n\n### System requirements\n\n- REQ-001: \n- NFR-001: \n\n## Use cases\n\n*Optional: delete this section when no user sees the change.*\n\n### Use case 1: [name]\n\n- **Actor:** \n- **Scenario:** \n- **Expected outcome:** \n\n## Architecture\n\n*Optional: delete this section when the change is technically simple.*\n\n### Overview\n\n*Describe the approach at a high level.*\n\n### Diagrams\n\n*Describe or link the component, sequence and deployment diagrams. Kairos draws a mermaid block.*\n\n## Detailed design\n\n*Say the technical approach and the important details.*\n\n## UI and UX design\n\n*Optional: delete this section when the initiative has no UI.*\n\n### Mockups\n\n### User flows\n\n### Design system\n\n*Say how the change uses the existing patterns of the UI.*\n\n## Testing strategy\n\n*Optional: delete this section when another initiative covers the tests.*\n\n### Unit tests\n\n### Integration tests\n\n### System tests\n\n## Alternatives considered\n\n*List the other approaches, and why the team did not choose them.*\n\n## Implementation plan\n\n*List the phases and their order. Kairos keeps the tasks of each phase as children of the initiative.*\n\n## Exit criteria\n\n*Move the initiative to Completed only when each item is true.*\n\n- [ ] The context and the goals are clear.\n- [ ] The design has enough detail for the tasks.\n- [ ] The implementation plan has clear phases.\n- [ ] The testing strategy is defined.\n- [ ] The dependencies are known and resolved.\n', 'initiative', NULL, E'Use when one objective needs more than one task, or the work of more than one person or team.'),
    ('Strategy', 'strategy', E'## Context\n\n*Say where the organization is now and what changed. Give facts and numbers.*\n\n## Direction\n\n*Say what the organization will do. Also say what it will stop doing.*\n\n## Measures\n\n*For each measure, give a target and a date. The measures show if the hypothesis is true.*\n\n| Measure | Target | Date |\n|---|---|---|\n|  |  |  |\n\n## Risks\n\n*List what can make the strategy fail, and the sign that shows it early.*\n\n## Exit criteria\n\n*Move the strategy to Active only when each item is true.*\n\n- [ ] The context and the direction are clear.\n- [ ] Each measure has a target and a date.\n- [ ] The people who own the strategy reviewed and approved it.\n', 'strategy', NULL, E'Use when the organization bets on a direction for many months, and many initiatives serve it.'),
    ('ADR', 'adr', E'## Context\n\n*Say which problem or force makes this decision necessary now. Give facts. Do not argue for an option here.*\n\n## Decision\n\n*Say the decision in the active voice: "We use X for Y." Number the points when there are many.*\n\n## Alternatives\n\n*Optional: delete this section when there is only one clear option. Write one row for each option that you considered, the chosen option too.*\n\n| Option | Pros | Cons | Risk (low, medium, high) | Cost |\n|---|---|---|---|---|\n|  |  |  |  |  |\n\n## Rationale\n\n*Say why the chosen option is better than the others. Connect each reason to the context.*\n\n## Consequences\n\n*List what becomes easier, what becomes harder, and what does not change. When the decision has a review date or a review condition, set the metadata `revisit_on` or `revisit_when`.*\n\n**Positive**\n\n- \n\n**Negative**\n\n- \n\n**Neutral**\n\n- \n\n## Exit criteria\n\n*Move the ADR to Decided only when each item is true.*\n\n- [ ] The context of the problem is clear.\n- [ ] The decision is stated.\n- [ ] The rationale says why the team chose this option.\n- [ ] The consequences are known and assessed.\n', 'adr', NULL, E'Use when you make a decision that is hard to change later, or that other teams must follow.'),
    ('Design Doc', 'design_doc', E'## Overview\n\n*Write this section last. From this section alone, a reader knows what the system is, why it exists, and what it can do.*\n\n### What it is\n\n*Say what the system is responsible for, not how it works inside. Ask: what stops when the system does not exist?*\n\n- **Responsibility**: one sentence about what it means in practice.\n\n### Why it exists\n\n*Name the problems of today. Write a fact, such as "teams define the same data in different ways", not "things are hard".*\n\n- \n\n### Capability areas\n\n*Put the main functions into two to four named areas. The PRD groups its requirements by these areas.*\n\n1. **Area**: one sentence.\n\n### Constraints\n\n*List what you cannot change: existing systems, hard dependencies, technical limits, business rules. A constraint is not a requirement: it is a limit that the requirements must fit in.*\n\n- **Constraint**: why it is a constraint and not a choice.\n\n### Principles\n\n*Write the rules that choose between two good solutions. Make them specific to this system.*\n\n- **Principle**: what it means in practice.\n\n## Documents of the design\n\n*Make each document that the design needs, with the same initiative as its parent, and write its code here. Delete a row when the design does not need that document.*\n\n| Document | Use it for | Code |\n|---|---|---|\n| PRD | What the system must do: the requirements. |  |\n| System Context | The actors and the external systems, and what each one gives and gets. |  |\n| Architecture Framing | The decisions that are open, and the limits on each one. |  |\n| ADR | Each decision, when the team makes it. One ADR for each decision. |  |\n\n## Open questions\n\n*List what you do not know yet. For each question, say what can answer it and who owns the answer.*\n\n- \n\n## Exit criteria\n\n*Publish the design only when each item is true.*\n\n- [ ] The overview says what the system is, why it exists, and what it can do.\n- [ ] Each document of the design exists, and the table has its code.\n- [ ] Each open question has an owner.\n', 'document', NULL, E'Use when you design a new system or a large feature. Start here: this document says which other documents the design needs.'),
    ('Runbook', 'runbook', E'*To test this runbook, give it to an engineer who was never on call for this service. Ask them to respond to an incident. When they stop, the runbook needs work.*\n\n## Quick reference\n\n*A person reads this first during an incident. Make it possible to read it in 30 seconds. Write facts only, and keep them current: an old fact is worse than no fact.*\n\n| | |\n|---|---|\n| On call | [paging tool and service] |\n| Chat | [alerts channel], [help channel] |\n| Incident channel | [how the team opens it] |\n| Production URL |  |\n| Logs | [log tool and dashboard] |\n| Dashboards |  |\n| Deployment | [pipeline or deploy procedure] |\n| Repository |  |\n| Escalation | See Escalation path. |\n\n## Service overview\n\n*Write two to four sentences: what the service does, who uses it, and what breaks when it fails. Say how large the damage is, not how the service is built.*\n\n### Criticality\n\n*Give the lowest severity of a failure, and why. Say if a failure wakes a person at night, or if it can wait for working hours.*\n\n| Lowest severity | Reason |\n|---|---|\n|  |  |\n\n### Dependencies\n\n*List each system that the service uses: databases, APIs, queues. Say what breaks in this service when each one fails.*\n\n| Dependency | Type | Effect when it fails |\n|---|---|---|\n|  |  |  |\n\n## Health checks\n\n*Say what a healthy service shows. A person must be able to confirm the health in two minutes. Give exact commands, URLs or dashboard panels.*\n\n### Signs of a healthy service\n\n- \n\n### How to check health\n\n```\n[command, URL or steps]\n```\n\n## Failure modes\n\n*Write one section for each failure that you know. Write it for a person who did not build the service. Each step is an action. When the answer is "it depends", split it into cases. A failure that caused an incident before goes here.*\n\n### [Failure, as the person on call sees it]\n\n**Symptoms:** what the alert says, what users report, what the logs show.\n\n**Likely causes**\n\n- \n\n**Diagnosis**\n\n```\n[commands or steps that find the cause]\n```\n\n**Resolution**\n\n```\n[steps for each cause]\n```\n\n**Escalate when:** [condition, for example "the service is not back 15 minutes after these steps"]\n\n## Procedures\n\n*Link the procedures that the person on call can need fast. The steps stay in the procedure.*\n\n| Procedure | When to use it | Link |\n|---|---|---|\n|  |  |  |\n\n## Escalation path\n\n*Name people, not only roles. Keep it current: an old escalation path fails at the worst time.*\n\n| Severity | First contact | How to reach them | Escalation |\n|---|---|---|---|\n|  |  |  |  |\n\n## Known issues\n\n*Write what the design does not show. For example: what failed before, what behaves strangely under load, what fails more often than it should.*\n\n- \n\n## Maintenance\n\n*Review this runbook after each incident that used it. Also review it each quarter, and after each change of the architecture or the dependencies.*\n\n## Exit criteria\n\n*Publish the runbook only when each item is true.*\n\n- [ ] An engineer who is new to the service can follow it.\n- [ ] The quick reference is current.\n- [ ] The runbook was reviewed after the last incident.\n', 'document', NULL, E'Use when a service runs in production and a person on call must keep it working.'),
    ('Postmortem', 'postmortem', E'## Summary\n\n*Write two to four sentences: what happened, who had the problem, and how the team fixed it. Example: "On 3 June, the reports API was slow for 53 minutes. A new endpoint ran a query with no index. Some clients got timeouts."*\n\n## Timeline\n\n*Write each event with its time and its time zone. Start at the first sign, not at the alert.*\n\n| Time | Event |\n|---|---|\n|  |  |\n\n## Impact\n\n*Give facts, with numbers where you can.*\n\n- **Start** (when the impact started, not when somebody saw it):\n- **Declared** (when the incident was opened):\n- **End:**\n- **Systems affected:**\n- **User impact** (for example, the percent of requests that failed):\n- **Service level or revenue impact** (when it applies):\n\n## Root causes\n\n*Ask "why" until you find causes that the team can change. Look for technical causes and for causes in the organization. A person is not a cause.*\n\n### Technical causes\n\n- \n\n### Organization causes\n\n- \n\n## What went well\n\n*Include the places where the team was lucky.*\n\n- \n\n## What could be better\n\n*Say what made the incident longer or worse: the detection, the tools, the documents or the handoffs.*\n\n- \n\n## Findings\n\n*For each finding, write a disposition (fix, mitigate, accept or defer) and the reason.*\n\n| Finding | Disposition | Reason |\n|---|---|---|\n|  |  |  |\n\n## Action items\n\n*Make a Kairos task for each action and write its code here. The task shows the owner, the date and the state.*\n\n| Action | Task |\n|---|---|\n|  |  |\n\n## Accepted risks\n\n*Write each risk that the team does not fix, why, when to look at it again, and who owns it.*\n\n| Risk | Why it is accepted | Review when | Owner |\n|---|---|---|---|\n|  |  |  |  |\n\n## Follow-up\n\n*Say when the team reviews the action items, who owns the follow-up, and who is told.*\n\n- **Review on:**\n- **Owner:**\n- **Who is told, and how:**\n\n## Exit criteria\n\n*Publish the postmortem only when each item is true.*\n\n- [ ] The timeline is complete.\n- [ ] The root causes are found.\n- [ ] Each action item has a Kairos task.\n- [ ] The team reviewed the postmortem.\n', 'document', NULL, E'Use when an incident is over. Learn from it and track the fixes. Write it without blame.')
